    var acquired=false;
    try {
        try{acquired=mutex.WaitOne(10000);}catch(System.Threading.AbandonedMutexException){acquired=true;}
        if(!acquired)throw new System.Exception("运行入口正在准备，请稍后重开。");
        if(!System.IO.File.Exists(installer)||hash(installer)!=expectedScript) {
            var temporary=installer+"."+System.Guid.NewGuid().ToString("N")+".tmp";
            try {
                System.IO.File.WriteAllText(temporary,script,new System.Text.UTF8Encoding(false));
                if(hash(temporary)!=expectedScript)throw new System.Exception("安装入口校验失败，未启动。");
                if(System.IO.File.Exists(installer))System.IO.File.Replace(temporary,installer,null);
                else System.IO.File.Move(temporary,installer);
            } finally {if(System.IO.File.Exists(temporary))System.IO.File.Delete(temporary);}
